"""Verify the output of run.py against expected OHLCV bars."""
import json
import sys
from pathlib import Path

EXPECTED = {
    ("2023-10-01T10:00:00Z", "AAPL"): {"open": 180.10, "high": 181.20, "low": 180.10, "close": 181.20, "volume": 23.0},
    ("2023-10-01T10:01:00Z", "AAPL"): {"open": 181.00, "high": 181.00, "low": 180.80, "close": 180.80, "volume": 19.0},
    ("2023-10-01T10:02:00Z", "AAPL"): {"open": 181.50, "high": 181.50, "low": 181.50, "close": 181.50, "volume": 15.0},
    ("2023-10-01T10:00:00Z", "MSFT"): {"open": 330.00, "high": 331.50, "low": 330.00, "close": 331.50, "volume": 7.0},
    ("2023-10-01T10:01:00Z", "MSFT"): {"open": 332.00, "high": 332.00, "low": 331.25, "close": 331.25, "volume": 8.0},
    ("2023-10-01T10:02:00Z", "MSFT"): {"open": 333.00, "high": 333.00, "low": 333.00, "close": 333.00, "volume": 1.0},
    ("2023-10-01T10:00:00Z", "GOOG"): {"open": 140.25, "high": 141.00, "low": 140.25, "close": 141.00, "volume": 5.0},
    ("2023-10-01T10:01:00Z", "GOOG"): {"open": 140.75, "high": 140.75, "low": 140.75, "close": 140.75, "volume": 5.0},
}


def main(path: str) -> int:
    rows = [json.loads(line) for line in Path(path).read_text().splitlines() if line.strip()]
    actual = {(r["window_start"], r["symbol"]): r for r in rows}

    required_keys = {"window_start", "symbol", "open", "high", "low", "close", "volume"}
    fail = 0
    for r in rows:
        if set(r.keys()) != required_keys:
            print(f"FAIL: row {r} has wrong keys: {sorted(r.keys())}")
            fail += 1

    if set(actual.keys()) != set(EXPECTED.keys()):
        missing = set(EXPECTED.keys()) - set(actual.keys())
        extra = set(actual.keys()) - set(EXPECTED.keys())
        if missing:
            print(f"FAIL: missing bars: {missing}")
        if extra:
            print(f"FAIL: extra bars: {extra}")
        fail += 1

    for key, exp in EXPECTED.items():
        got = actual.get(key)
        if got is None:
            continue
        for field, value in exp.items():
            if abs(float(got[field]) - float(value)) > 1e-9:
                print(f"FAIL: {key} {field}: expected {value}, got {got[field]}")
                fail += 1

    if fail == 0:
        print(f"PASS: all {len(EXPECTED)} bars match expected values exactly")
        return 0
    print(f"FAIL: {fail} check(s) failed")
    return 1


if __name__ == "__main__":
    raise SystemExit(main(sys.argv[1]))
